mapper.update:
update agent_run
set status = #{status},
    error_message = #{errorMessage},
    ended_at = #{endedAt}
where 1 = 1
  and run_id = #{runId}

update agent_run
set tool_call_count = tool_call_count + #{delta}
where 1 = 1
  and run_id = #{runId}

update agent_run
set tool_denied_count = tool_denied_count + #{delta}
where 1 = 1
  and run_id = #{runId}
